// Client for the precise fabric visualizer — runs ENTIRELY IN THE BROWSER.
//
// The heavy lifting lives in lib/browserVisualizer/ (CLIPSeg + SlimSAM via
// transformers.js for upholstery masking, deterministic canvas-math
// compositing for the exact-pattern transfer). No server, no API keys, no
// per-image cost; photos never leave the visitor's device. Models (~180MB)
// download from the Hugging Face CDN on first use and are cached by the
// browser afterwards.
//
// Furniture templates ship with pre-baked upholstery masks
// (public/assets/furniture-templates/{id}_mask.png, generated by
// scripts/make-template-masks.mjs), so template generations skip
// segmentation entirely and finish in well under a second once models for
// uploads aren't even needed.

// Catalog swatch images carry a text label in the bottom-right corner; the
// tiler uses only this top-left fraction of them.
const CATALOG_SWATCH_CROP = 0.72;

export function isPreciseModeAvailable() {
  return typeof window !== "undefined" && typeof WebAssembly !== "undefined";
}

export async function fetchCatalogFabricBlob(imagePath) {
  const res = await fetch(imagePath);
  if (!res.ok) throw new Error("Could not load the catalog fabric image.");
  return res.blob();
}

const PHASE_MESSAGES = {
  models: "Downloading the AI models (first visit only)…",
  locating: "Finding the upholstery…",
  masking: "Refining the mask…",
  compositing: "Applying your fabric…",
};

function phaseText(phase, progress) {
  const base = PHASE_MESSAGES[phase] || "Working…";
  if (phase === "models" && progress !== undefined) {
    return `${base} ${Math.round(progress * 100)}%`;
  }
  return base;
}

// In-memory cache of template photo + baked mask (RawImage + Uint8Array).
const templateCache = new Map();

async function loadTemplate(templateId, RawImage) {
  if (templateCache.has(templateId)) return templateCache.get(templateId);

  const base = `/assets/furniture-templates/${templateId}`;
  const [photoRes, maskRes] = await Promise.all([fetch(`${base}.jpg`), fetch(`${base}_mask.png`)]);
  if (!photoRes.ok) throw new Error("Template photo is missing.");
  const furniture = await RawImage.fromBlob(await photoRes.blob());

  let mask = null;
  if (maskRes.ok) {
    const maskImg = (await RawImage.fromBlob(await maskRes.blob())).grayscale();
    if (maskImg.width === furniture.width && maskImg.height === furniture.height) {
      mask = new Uint8Array(maskImg.width * maskImg.height);
      for (let i = 0; i < mask.length; i++) mask[i] = maskImg.data[i] > 127 ? 255 : 0;
    }
  }

  const entry = { furniture, mask };
  templateCache.set(templateId, entry);
  return entry;
}

function rgbaToJpegDataUrl(rgba, width, height, quality = 0.92) {
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  canvas.getContext("2d").putImageData(new ImageData(rgba, width, height), 0, 0);
  return canvas.toDataURL("image/jpeg", quality);
}

function maskToPngDataUrl(mask, width, height) {
  const rgba = new Uint8ClampedArray(width * height * 4);
  for (let i = 0; i < mask.length; i++) {
    const v = mask[i];
    const o = i * 4;
    rgba[o] = v;
    rgba[o + 1] = v;
    rgba[o + 2] = v;
    rgba[o + 3] = 255;
  }
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  canvas.getContext("2d").putImageData(new ImageData(rgba, width, height), 0, 0);
  return canvas.toDataURL("image/png");
}

/**
 * Run the precise in-browser generation.
 *
 * @param {object} opts
 * @param {File|Blob|null} opts.furnitureFile uploaded furniture photo (XOR templateId)
 * @param {string|null} opts.templateId one of the FURNITURE_TEMPLATES ids
 * @param {File|Blob|null} opts.fabricFile uploaded swatch (XOR fabricImagePath)
 * @param {string|null} opts.fabricImagePath catalog swatch path under /assets
 * @param {number} opts.fabricScale pattern repeat multiplier (0.5–2 from the UI)
 * @param {boolean} [opts.returnMask] include the mask data URL (dev overlay)
 * @param {(text: string) => void} [opts.onProgress] human-readable phase updates
 * @returns {Promise<{image: string, mask: string|null, meta: object}>}
 */
export async function generatePrecise({
  furnitureFile,
  templateId,
  fabricFile,
  fabricImagePath,
  fabricScale,
  returnMask,
  onProgress,
}) {
  const [{ generateVisualization, SegmentationFailed }, { RawImage }] = await Promise.all([
    import("./browserVisualizer/pipeline.mjs"),
    import("@huggingface/transformers"),
  ]);

  const onPhase = (phase, progress) => onProgress?.(phaseText(phase, progress));

  try {
    let furniture;
    let precomputedMask = null;
    if (templateId) {
      onProgress?.("Preparing the template…");
      ({ furniture, mask: precomputedMask } = await loadTemplate(templateId, RawImage));
    } else {
      furniture = await RawImage.fromBlob(furnitureFile);
    }

    const swatchBlob = fabricFile || (await fetchCatalogFabricBlob(fabricImagePath));
    const swatch = await RawImage.fromBlob(swatchBlob);

    const result = await generateVisualization({
      furniture,
      swatch,
      fabricScale,
      swatchCrop: fabricFile ? 1 : CATALOG_SWATCH_CROP,
      precomputedMask,
      onPhase,
    });

    return {
      image: rgbaToJpegDataUrl(result.rgba, result.width, result.height),
      mask: returnMask ? maskToPngDataUrl(result.mask, result.width, result.height) : null,
      meta: result.meta,
    };
  } catch (err) {
    if (err instanceof SegmentationFailed || err?.code === "segmentation_failed") {
      const friendly = new Error(
        "We couldn't detect the upholstered areas in that photo. Try a clearer, front-on photo of the furniture."
      );
      friendly.code = "segmentation_failed";
      throw friendly;
    }
    throw err;
  }
}
